<?php
namespace App\Http\Controllers; use App\Models\{Item,Category}; use Illuminate\Http\Request;
class ItemController extends Controller {public function index(Request $r){$q=Item::with('category');if($r->filled('q'))$q->where('name','like','%'.$r->q.'%');if($r->filled('category_id'))$q->where('category_id',$r->category_id);return view('items.index',['items'=>$q->latest()->paginate(20)->withQueryString(),'categories'=>Category::orderBy('name')->get()]);} public function create(){return view('items.form',['item'=>new Item,'categories'=>Category::orderBy('name')->get()]);} public function store(Request $r){$d=$this->validateItem($r);$item=Item::create($d);return redirect('/items')->with('success','Item save ho gaya.');} public function edit(Item $item){return view('items.form',['item'=>$item,'categories'=>Category::orderBy('name')->get()]);} public function update(Request $r,Item $item){$item->update($this->validateItem($r,$item->id));return redirect('/items')->with('success','Item update ho gaya.');} public function destroy(Item $item){if($item->saleItems()->exists()||$item->purchaseItems()->exists())return back()->with('error','Is item ki sale/purchase history hai; delete nahi kar sakte.');$item->delete();return back()->with('success','Item delete ho gaya.');} private function validateItem(Request $r,$id=null){return $r->validate(['category_id'=>'nullable|exists:categories,id','sku'=>'nullable|string|max:100|unique:items,sku'.($id?','.$id:''),'name'=>'required|string|max:255','brand'=>'nullable|string|max:255','source_sheet'=>'nullable|string|max:100','description'=>'nullable|string','buying_price'=>'required|numeric|min:0','selling_price'=>'required|numeric|min:0','quantity'=>'required|integer|min:0','low_stock_limit'=>'required|integer|min:0']);}}
